    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We use a quadratic penalty to discourage leaving large empty gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead Synergy: If post_residual can accommodate the next item, 
    // heavily reward this bin to minimize future bin openings.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 15.0;
        // Further reward if it creates a "perfect fit" (0 residual after next item)
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // 3. New Bin Thresholding: If we are forced to open a new bin, penalize it 
    // unless the current open bins are extremely inefficient (mean_residual is high).
    if bin_residual == bin_capacity {
        score += 85.0; // Base cost of opening a new bin
        if mean_residual < 25.0 {
            score += 40.0; // Penalize new bins if current ones are fairly empty
        }
    }

    // 4. Scarcity Logic: If this is the only bin that fits the item, 
    // favor using it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // 5. Progression Adjustment: As the stream nears the end, become more 
    // conservative about leaving space (prevent stranding items).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual).
    // Penalize large residuals quadratically to avoid fragmentation.
    let mut score = post * post / 10.0;

    // Favor bins that preserve enough space for the next item (Lookahead).
    // If post_residual is slightly less than next_item_size, we create "dead space".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 5.0;
        }
    }

    // Dynamic pressure: As the stream nears the end, become more aggressive 
    // about filling bins tightly to avoid opening new ones.
    let tightness_bonus = (1.0 - progress) * (bin_capacity - post_residual) as f64;
    score -= tightness_bonus;

    // Penalty for opening a new bin (bin_residual == bin_capacity).
    // This scales with the number of open bins; we prefer to use existing capacity
    // unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 80.0 + (open_bins_count as f64 * 2.5);
    }

    // Penalty for leaving a bin with a "useless" residual (too small for any item).
    // Assuming min item size is 10, residuals < 10 are highly undesirable.
    if post_residual < 10 && post_residual > 0 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Interaction term: If this is the last fitting bin, prioritize it to keep 
    // the bin count low, unless the fit is catastrophically bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
