pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any likely future item.
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead matching: If post_residual is close to next_item_size, we favor this bin
    // because it enables a tight packing of the upcoming item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements that leave exactly enough room for the next item
        if post_residual >= next_item_size {
            score -= (50.0 - diff) * 1.5;
        } else {
            // Penalize if the next item cannot fit in the remaining space
            score += 20.0;
        }
    }

    // 3. Global state awareness: If we are near the end of the stream, prioritize 
    // filling existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

    // 4. Mean residual balancing: Penalize bins that deviate significantly from 
    // the mean residual of all open bins (encouraging uniform distribution).
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. New Bin Logic: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the penalty for using existing bins is extremely high.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced by the number of bins already open
        // to prevent fragmentation, but generally kept high.
        score = 85.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin and it's the only one that fits, give it a massive priority boost.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are too small to fit common items (10-30 range)
    // We create a "valley" of desirability around the mid-range of post_residual
    let waste_penalty = if post < 15.0 { (15.0 - post).powi(2) * 2.0 } else { 0.0 };

    // Favor bins that leave room for the lookahead item
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 5.0
    } else {
        0.0
    };

    // Dynamic sensitivity: as the stream progresses, prioritize tighter packing (lower residuals)
    // to avoid fragmentation near the end of the stream
    let tightness_factor = 1.0 + (progress * 3.0);

    // Evaluate new bin opening vs existing
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // Only open new if existing bins are poor fits or we are forced
        (fitting_bins_count as f64 * 10.0) + (progress * 20.0)
    } else {
        0.0
    };

    // Combine metrics:
    // 1. Post residual (base)
    // 2. Waste penalty (non-linear)
    // 3. Lookahead compatibility
    // 4. New bin avoidance
    let score = (post * tightness_factor) + waste_penalty + lookahead_penalty + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit approach).
    // We want to minimize this, so smaller post_residual is better.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As we near the end of the stream, opening a new bin is increasingly costly.
    if is_new_bin {
        score += 15.0 + (progress * 40.0);
    }

    // Lookahead logic: If the next item exists, penalize bins that cannot fit it.
    // If post_residual is too small to fit next_item_size, we might create dead space.
    if next_item_size > 0 && !is_new_bin {
        if post_residual < next_item_size {
            // Penalize creating a "dead" gap that cannot accommodate the next item.
            // The penalty is modulated by how much the residual deviates from the mean.
            score += (post_residual as f64 * 0.5) + (mean_residual * 0.2);
        } else {
            // Reward bins that can accommodate the next item.
            score -= (next_item_size as f64 * 0.8);
        }
    }

    // Fitting bins count influence:
    // If this is the only bin that fits, we are forced to use it.
    // We make this choice very attractive to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Non-linear coupling: 
    // Penalize very small residuals (fragmentation) if we are early in the stream,
    // but accept them later to pack tightly.
    let fragmentation_penalty = if post_residual < 10 && post_residual > 0 {
        10.0 * (1.0 - progress)
    } else {
        0.0
    };

    score + fragmentation_penalty
}

