        score -= 5.0;
    }

    // 6. Mean residual balancing: Penalize placing items in bins that are already 
    // "fuller" than the average to keep the distribution of residuals uniform.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

